#!/usr/bin/env bash
# HRD-070 round 7: copy of the r6 harness; only change is that X18 now sits in the must-be-KILLED section (killed by TestHRD070ParseCaseVariantEncryptionMember). Run with ONLY= to repeat a subset.
set -u
H=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd); R=${R:-$(cd "$H/../../../.." && pwd)}; S=${S:-$(mktemp -d)}; export GOFLAGS=
rm -rf "${S:?}/w"; : >"$S/edits.txt"; mkdir -p "$S/w"; cp -r "$R/core" "$R/server" "$S/w/"; [ -f "$R/go.work" ] && cp "$R/go.work" "$S/w/"; : 
EXPECT=KILLED; NRUN=0
run() { # name dir pkg file sedexpr runre
  local name=$1 dir=$2 pkg=$3 file=$4 expr=$5 re=$6 rc
  if [ -n "${ONLY:-}" ] && ! [[ $name =~ $ONLY ]]; then return; fi
  NRUN=$((NRUN+1)); if [ -n "${SHARDS:-}" ] && [ $((NRUN % SHARDS)) -ne "${SHARD:-0}" ]; then return; fi
  ( cd "$S/w/$dir" && cp "$file" "$file.orig" && sed -i "$expr" "$file" && ! cmp -s "$file" "$file.orig" ) || { echo "MUTANT $name: NOT APPLIED"; ( cd "$S/w/$dir" && [ -f "$file.orig" ] && mv "$file.orig" "$file" ); return; }
  echo "MUTANT-EDITS $name: $dir/$file $(diff "$S/w/$dir/$file.orig" "$S/w/$dir/$file" | awk -F'[acd]' '/^[0-9]/{split($1,a,","); b=(a[2]!=""?a[2]:a[1]); printf "%s%s-%s", (n++?",":""), a[1], b}')" >>"$S/edits.txt"
  ( cd "$S/w/$dir" && go test "$pkg" -run "$re" -count=1 -timeout 180s >"$S/$name.out" 2>&1 ); rc=$?
  if grep -qE "\[build failed\]|\[setup failed\]" "$S/$name.out"; then
    echo "MUTANT $name: NOT APPLIED (mutant does not compile; a compile error is not a kill)"
  elif [ $rc -eq 0 ]; then
    if [ "$EXPECT" = SURVIVED ]; then echo "MUTANT $name: SURVIVED (equivalent, expected)"; else echo "MUTANT $name: SURVIVED (BAD)"; fi
  else
    if [ "$EXPECT" = SURVIVED ]; then echo "MUTANT $name: KILLED (BAD: expected equivalent)"; else echo "MUTANT $name: KILLED"; fi
    grep -m2 -E "^\s+--- FAIL|FAIL:|fuzz_test|lcpfuzz_test" "$S/$name.out" | head -2
  fi
  grep "^MUTANT-EDITS $name:" "$S/edits.txt" | sed 's/^MUTANT-EDITS [^:]*: /  edits /'
  ( cd "$S/w/$dir" && mv "$file.orig" "$file" )
  ( cd "$S/w/$dir" && go test "$pkg" -run "$re" -count=1 >/dev/null 2>&1 ) && echo "  restored: GREEN again" || echo "  restored: STILL RED (BAD)"
}
